register:
using Exsited.Client;
using Exsited.Config;

ClientRegistry.RegisterInstances(new object[]
{
    new SdkConfig(
        new AuthConfig(
            clientName: "default",
            baseUrl: Environment.GetEnvironmentVariable("EXSITED_BASE_URL") ?? "",
            clientId: Environment.GetEnvironmentVariable("EXSITED_CLIENT_ID") ?? "",
            clientSecret: Environment.GetEnvironmentVariable("EXSITED_CLIENT_SECRET") ?? "",
            redirectUri: Environment.GetEnvironmentVariable("EXSITED_REDIRECT_URI") ?? ""),
        raiseOnError: true),
});
